const TAU = Math.PI * 2;
const cx = api.w / 2, cy = api.h / 2;
const nb = Math.max(1, Math.round(p.beams));

// faint ambient halo, breathes once per loop
const breathe = 0.5 + 0.5 * Math.sin(TAU * api.t);
api.circle(cx, cy, p.bloom * 1.1 + 0.5 * breathe, 3, 0.09 * p.intensity);

for (let b = 0; b < nb; b++) {
  const a = TAU * (api.t + b / nb);
  const sx = Math.sin(a), depth = Math.cos(a);
  // beam only exists when it is not pointing straight at/away from the viewer
  const side = Math.abs(sx);
  if (side > 0.06) {
    const dir = sx >= 0 ? 1 : -1;
    const len = side * p.reach * api.w * 0.55;
    const steps = Math.max(2, Math.round(len));
    for (let s = 1; s <= steps; s++) {
      const f = s / steps;
      const x = Math.round(cx + dir * f * len);
      // wedge: narrow at the lamp, flaring out
      const hh = p.taper * (0.5 + f * 2.6);
      const h = Math.max(1, Math.round(hh * 2));
      const y = Math.round(cy - hh);
      const fall = (1 - f * 0.85);
      const base = fall * fall * side * p.intensity;
      // soft outer wedge
      const ao = 0.30 * base;
      if (ao > 0.03) api.rect(x, y, 1, h, 3, ao);
      // brighter inner wedge, half height
      const hi = Math.max(1, Math.round(hh));
      const ai = 0.45 * base;
      if (ai > 0.03) api.rect(x, Math.round(cy - hi * 0.5), 1, hi, 2, ai);
      // hard hot core line down the axis, fades out fastest
      const ac = 0.85 * fall * fall * fall * side * p.intensity;
      if (ac > 0.05) api.px(x, Math.round(cy), f < 0.5 ? 0 : 1, ac);
    }
  }
  // head-on flare: beam swinging toward the viewer blooms the lamp
  const face = (1 - depth) / 2;
  const bl = face * face * face;
  if (bl > 0.02) {
    api.circle(cx, cy, p.bloom * (0.9 + 1.8 * bl), 3, 0.14 * bl * p.intensity);
    api.circle(cx, cy, p.bloom * (0.5 + 1.0 * bl), 2, 0.30 * bl * p.intensity);
    api.circle(cx, cy, p.bloom * (0.22 + 0.5 * bl), 1, 0.55 * bl * p.intensity);
  }
}

// the lamp itself: small, hard, always the brightest thing on the sheet
api.circle(cx, cy, 2.0, 2, 0.5 * p.intensity);
api.circle(cx, cy, 1.2, 0, 0.9 * p.intensity);
api.px(Math.round(cx), Math.round(cy), 0, p.intensity);
api.px(Math.round(cx) - 1, Math.round(cy), 0, 0.7 * p.intensity);
api.px(Math.round(cx) + 1, Math.round(cy), 0, 0.7 * p.intensity);
